-- Schema for MyBatis version of backend (previously auto-generated by Hibernate ddl-auto=update)
-- Statements are idempotent so this file can safely run on every application startup
-- (spring.sql.init.mode=always in application.properties).

CREATE TABLE IF NOT EXISTS tbl_member (
                                          email    VARCHAR(100) NOT NULL,
    pw       VARCHAR(100) NOT NULL,
    nickname VARCHAR(50)  NOT NULL,
    social   BOOLEAN      NOT NULL DEFAULT FALSE,
    PRIMARY KEY (email)
    );

CREATE TABLE IF NOT EXISTS tbl_member_role (
                                               member_email VARCHAR(100) NOT NULL,
    role_name    VARCHAR(20)  NOT NULL,
    CONSTRAINT fk_member_role_email FOREIGN KEY (member_email) REFERENCES tbl_member (email)
    );

-- LDH 시작
CREATE TABLE IF NOT EXISTS tbl_member_social (
                                                 id             BIGINT AUTO_INCREMENT,
    member_email   VARCHAR(100) NOT NULL,
    provider       VARCHAR(20)  NOT NULL,
    provider_id    VARCHAR(100) NOT NULL,
    provider_email VARCHAR(100),
    connected_at   DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_member_social_provider (provider, provider_id),
    UNIQUE KEY uk_member_social_member_provider (member_email, provider),
    CONSTRAINT fk_member_social_email FOREIGN KEY (member_email) REFERENCES tbl_member (email)
    );

CREATE TABLE IF NOT EXISTS tbl_member_refresh_token (
                                                        id BIGINT AUTO_INCREMENT,
    member_email VARCHAR(100) NOT NULL,
    session_id VARCHAR(36) NOT NULL,
    selected_profile_id BIGINT NULL,
    token_hash VARCHAR(64) NOT NULL,
    expires_at DATETIME NOT NULL,
    revoked BOOLEAN NOT NULL DEFAULT FALSE,
    used_at DATETIME,
    user_agent VARCHAR(255),
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_member_refresh_token_hash (token_hash),
    INDEX idx_member_refresh_token_session_id (session_id),
    INDEX idx_member_refresh_token_member_email (member_email),
    CONSTRAINT fk_member_refresh_token_member FOREIGN KEY (member_email) REFERENCES tbl_member (email)
    );

CREATE TABLE IF NOT EXISTS tbl_family (
                                          family_id BIGINT AUTO_INCREMENT,
    family_name VARCHAR(100) NOT NULL,
    invite_code VARCHAR(20) NOT NULL,
    created_by VARCHAR(100) NOT NULL,
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (family_id),
    UNIQUE KEY uk_family_invite_code (invite_code),
    CONSTRAINT fk_family_created_by FOREIGN KEY (created_by) REFERENCES tbl_member (email)
    );

CREATE TABLE IF NOT EXISTS tbl_family_member (
                                                 id BIGINT AUTO_INCREMENT,
                                                 family_id BIGINT NOT NULL,
                                                 member_email VARCHAR(100) NOT NULL,
    family_role VARCHAR(20) NOT NULL DEFAULT 'MEMBER',
    parent_type VARCHAR(20) NOT NULL,
    joined_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id),
    UNIQUE KEY uk_family_member_email (member_email),
    UNIQUE KEY uk_family_member_pair (family_id, member_email),
    CONSTRAINT fk_family_member_family FOREIGN KEY (family_id) REFERENCES tbl_family (family_id),
    CONSTRAINT fk_family_member_member FOREIGN KEY (member_email) REFERENCES tbl_member (email)
    );

CREATE TABLE IF NOT EXISTS tbl_hospital_reservation (
    reservation_no BIGINT AUTO_INCREMENT,
    member_email VARCHAR(100) NOT NULL,
    hospital_id VARCHAR(100) NOT NULL,
    hospital_name VARCHAR(100) NOT NULL,
    hospital_type VARCHAR(100),
    hospital_address VARCHAR(300),
    hospital_phone VARCHAR(50),
    reservation_date DATE NOT NULL,
    reservation_time VARCHAR(10) NOT NULL,
    patient_name VARCHAR(50),
    message VARCHAR(500),
    status VARCHAR(20) NOT NULL DEFAULT 'REQUESTED',
    reg_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mod_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (reservation_no),
    CONSTRAINT fk_hospital_reservation_member FOREIGN KEY (member_email) REFERENCES tbl_member (email),
    INDEX idx_hospital_reservation_member (member_email, status),
    INDEX idx_hospital_reservation_hospital (hospital_id, reservation_date)
);

CREATE TABLE IF NOT EXISTS tbl_member_profile (
                                                  profile_id BIGINT AUTO_INCREMENT,
                                                  member_email VARCHAR(100) NOT NULL,
    profile_name VARCHAR(50) NOT NULL,
    parent_type VARCHAR(20) NOT NULL,
    profile_image_file_name VARCHAR(500),
    active BOOLEAN NOT NULL DEFAULT TRUE,
    reg_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mod_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (profile_id),
    CONSTRAINT fk_member_profile_member FOREIGN KEY (member_email) REFERENCES tbl_member (email),
    INDEX idx_member_profile_member (member_email, active)
    );

ALTER TABLE tbl_member_refresh_token ADD COLUMN IF NOT EXISTS selected_profile_id BIGINT NULL;

