    PRIMARY KEY (job_no, day_of_week),
    CONSTRAINT fk_babysitter_job_desired_day_job FOREIGN KEY (job_no) REFERENCES tbl_babysitter_job_post (job_no)
);

ALTER TABLE tbl_babysitter_job_post ADD COLUMN IF NOT EXISTS latitude DECIMAL(10,7) NULL;
ALTER TABLE tbl_babysitter_job_post ADD COLUMN IF NOT EXISTS longitude DECIMAL(10,7) NULL;

-- KYI - 베이비시터 구인글 지원
CREATE TABLE IF NOT EXISTS tbl_babysitter_job_application (
    application_no BIGINT AUTO_INCREMENT,
    job_no         BIGINT       NOT NULL,
    sitter_email   VARCHAR(100) NOT NULL,
    message        VARCHAR(500),
    status         VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    reg_time       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    mod_time       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (application_no),
    CONSTRAINT fk_babysitter_job_application_job FOREIGN KEY (job_no) REFERENCES tbl_babysitter_job_post (job_no),
    CONSTRAINT fk_babysitter_job_application_sitter FOREIGN KEY (sitter_email) REFERENCES tbl_babysitter_profile (email),
    CONSTRAINT uq_babysitter_job_application UNIQUE (job_no, sitter_email)
);

-- KYI - 베이비시터 후기 (요청 1건당 후기 1개)
CREATE TABLE IF NOT EXISTS tbl_babysitter_review (
    review_no    BIGINT AUTO_INCREMENT,
    request_no   BIGINT       NOT NULL,
    sitter_email VARCHAR(100) NOT NULL,
    writer_email VARCHAR(100) NOT NULL,
    rating       INT          NOT NULL,
    content      VARCHAR(500),
    reg_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (review_no),
    CONSTRAINT fk_babysitter_review_request FOREIGN KEY (request_no) REFERENCES tbl_babysitter_request (request_no),
    CONSTRAINT fk_babysitter_review_sitter FOREIGN KEY (sitter_email) REFERENCES tbl_babysitter_profile (email),
    CONSTRAINT fk_babysitter_review_writer FOREIGN KEY (writer_email) REFERENCES tbl_member (email),
    UNIQUE KEY uq_babysitter_review_request (request_no)
);

-- KYI - 베이비시터 채팅방 (부모-시터 1:1)
CREATE TABLE IF NOT EXISTS tbl_babysitter_chat_room (
    room_no      BIGINT AUTO_INCREMENT,
    parent_email VARCHAR(100) NOT NULL,
    sitter_email VARCHAR(100) NOT NULL,
    reg_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (room_no),
    CONSTRAINT fk_babysitter_chat_room_parent FOREIGN KEY (parent_email) REFERENCES tbl_member (email),
    CONSTRAINT fk_babysitter_chat_room_sitter FOREIGN KEY (sitter_email) REFERENCES tbl_babysitter_profile (email),
    UNIQUE KEY uq_babysitter_chat_room (parent_email, sitter_email)
);
-- 안읽음 배지용: 각자(부모/시터)가 마지막으로 읽은 메시지 번호
ALTER TABLE tbl_babysitter_chat_room ADD COLUMN IF NOT EXISTS parent_last_read_msg_no BIGINT NOT NULL DEFAULT 0;
ALTER TABLE tbl_babysitter_chat_room ADD COLUMN IF NOT EXISTS sitter_last_read_msg_no BIGINT NOT NULL DEFAULT 0;

-- KYI - 베이비시터 채팅 메시지
CREATE TABLE IF NOT EXISTS tbl_babysitter_chat_message (
    msg_no         BIGINT AUTO_INCREMENT,
    room_no        BIGINT       NOT NULL,
    sender_email   VARCHAR(100) NOT NULL,
    msg_type       VARCHAR(10)  NOT NULL DEFAULT 'TEXT', -- TEXT | REQUEST
    content        VARCHAR(1000),
    request_no     BIGINT,                               -- REQUEST 타입일 때만: 채팅 안에서 보낸 시터 요청 카드가 가리키는 실제 요청
    request_status VARCHAR(20),                           -- REQUEST 타입 카드 렌더링용 스냅샷(PENDING/ACCEPTED/REJECTED) - 진실은 tbl_babysitter_request.status
    reg_time       DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (msg_no),
    CONSTRAINT fk_babysitter_chat_message_room FOREIGN KEY (room_no) REFERENCES tbl_babysitter_chat_room (room_no),
