    amount       INT NOT NULL,              -- +적립 / -차감
    reason       VARCHAR(100) NOT NULL,     -- QUEST | CHALLENGE_SUCCESS | CHALLENGE_FAIL | MONTHLY
    ref_id       BIGINT NULL,
