    issued_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    used_at      DATETIME NULL,
    PRIMARY KEY (id),
    CONSTRAINT fk_mcoupon_member FOREIGN KEY (member_email) REFERENCES tbl_member (email),
